return [{
  json: {
    query: 'SELECT count(1) as total_ticks_v3 FROM mdds_ticks_v3 WHERE sending_time >= CURRENT_DATE AND sending_time < CURRENT_DATE + INTERVAL \'1 day\';',
    database: 'timescale',
    environment: 'prod',
    _triggerSource: 'executeWorkflow'
  }
}];

const input = $input.first();
const res = (input && input.json) || {};

// ── Xử lý lỗi khi truy vấn Metabase thất bại ────────────────────────────────
if (res.isError || !res.success) {
  const errMsg = res.reportText || res.message || 'Lỗi kết nối hoặc phiên đăng nhập Metabase hết hạn';
  return [{
    json: {
      environment: 'PRODUCTION',
      timestamp: new Date().toISOString(),
      rowCount: 0,
      isHealthy: false,
      message: res.reportText || `🚨 **[TimescaleDB MDDS Watchdog LỖI]** Không thể truy vấn Metabase Production:\n> ${errMsg}`
    }
  }];
}

// ── Kiểm tra tính toàn vẹn dữ liệu MDDS ─────────────────────────────────────
const firstRow = (res.data && res.data[0]) || {};
const rowCount = parseInt(firstRow.total_ticks_v3 || firstRow.count || res.rowCount || 0, 10);
const isHealthy = rowCount > 0;

return [{
  json: {
    environment: 'PRODUCTION',
    timestamp: new Date().toISOString(),
    rowCount: rowCount,
    isHealthy: isHealthy,
    message: isHealthy 
      ? `✅ **[TimescaleDB MDDS PROD]** Dữ liệu Ticks V3 hôm nay ổn định: **${rowCount.toLocaleString()}** records.` 
      : `🚨 **[TimescaleDB MDDS PROD CẢNH BÁO]** Không tìm thấy dữ liệu Ticks V3 cho phiên hôm nay!`
  }
}];
